SELECT ?film ?director ?dirLabel WHERE {
  VALUES ?film { dbr:La_otra_imagen dbr:The_Gentle_Art_of_Burglary }
  ?film dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?dirLabel . FILTER(lang(?dirLabel)='en') }
}

SELECT ?film ?filmLabel ?director ?dirLabel ?deathDate ?deathYear WHERE {
  VALUES ?film { dbr:La_otra_imagen dbr:The_Gentle_Art_of_Burglary }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:deathDate ?deathDate . }
  OPTIONAL { ?director dbo:deathYear ?deathYear . }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel)='en') }
  OPTIONAL { ?director rdfs:label ?dirLabel . FILTER(lang(?dirLabel)='en') }
}

SELECT ?film ?filmLabel ?director ?dirLabel ?deathDate WHERE {
  VALUES ?film { dbr:La_otra_imagen dbr:The_Gentle_Art_of_Burglary }
  ?film dbo:director ?director .
  ?director dbo:deathDate ?deathDate .
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel)='en') }
  OPTIONAL { ?director rdfs:label ?dirLabel . FILTER(lang(?dirLabel)='en') }
}
ORDER BY ?deathDate
LIMIT 1

